export const AFZ_QA_HPC_006: GeneratedProtocol = {
  code: "AFZ-QA-HPC-006",
  name: "African Black Soap, Cosmetics & Personal Care",
  version: "1.0",
  productClasses: ["black-soap", "cosmetic", "personal-care", "topical-wellness"],
  inheritsCoreSeverity: false,
  sections: [
    { letter: "A", title: "Legal & Regulatory Compliance" },
    { letter: "G", title: "Raw Material Quality — Oils & Fats" },
    { letter: "H", title: "GMP, Hygiene & Personnel" },
    { letter: "J", title: "Export Readiness, Recall & Traceability" },
  ],
  checkpoints: [
    { ref: "A.1", section: "A", order: 1, text: "Valid NAFDAC Certificate of Registration for the soap product, issued under the Cosmetic Products Regulations 2023. The NAFDAC number must appear on the label and match the certificate on file.", evidenceNote: "Current NAFDAC certificate; label artwork." },
    { ref: "A.2", section: "A", order: 2, text: "Valid business registration (CAC Certificate of Incorporation or Business Name Registration) in the name of the producing entity.", evidenceNote: "CAC certificate; business name registration document." },
    { ref: "A.3", section: "A", order: 3, text: "Trademark registration for the brand name/logo, or evidence of application. NAFDAC requires trademark registration for full cosmetic product registration; it is optional only at the micro-scale MSME tier.", evidenceNote: "Trademark certificate or application receipt (TRPC)." },
    { ref: "A.4", section: "A", order: 4, text: "If the product is exported, relevant destination-market cosmetic registrations are in place or in progress (EU CPNP notification; UK Cosmetic Notification Portal; USA FDA Voluntary Cosmetic Registration where applicable).", evidenceNote: "Export registration documents; CPNP or equivalent notification confirmation." },
    { ref: "A.5", section: "A", order: 5, text: "No prohibited substances are present in the formula. Cross-reference the INCI list against NAFDAC banned ingredients and EU Regulation 1223/2009 Annex II (prohibited substances list).", evidenceNote: "INCI list vs. NAFDAC banned list and EU Annex II." },
    { ref: "B.1", section: "B", order: 1, text: "Organic certification is current (not expired), issued by a recognised certifying body, and covers the specific ingredients and harvest year being used in current production batches.", evidenceNote: "Organic certificates — check expiry date, certifying body, and scope." },
    { ref: "B.2", section: "B", order: 2, text: "The percentage organic content stated on the label or in marketing is substantiated by calculation using ISO 16128-2:2017 or equivalent methodology. Self-declared percentages without a documented calculation are not acceptable.", evidenceNote: "ISO 16128-2 calculation worksheet or certifying body verification." },
    { ref: "B.3", section: "B", order: 3, text: "Cocoa pod source farms are documented — name, location, and certification status. The supplier can trace any current production batch to the specific certified farm or cooperative from which the cocoa pods were sourced.", evidenceNote: "Cocoa pod sourcing register; farm certificates; delivery receipts." },
    { ref: "B.4", section: "B", order: 4, text: "No synthetic fragrances, artificial colours, synthetic preservatives, or petroleum-derived ingredients are present in the formula. If an additive is present, it is identified by INCI name and its natural/organic status is substantiated.", evidenceNote: "Formula / INCI list cross-check." },
    { ref: "B.5", section: "B", order: 5, text: "No misleading claims: the product is not described as 'chemical-free' (all matter is chemical), 'preservative-free' (soap is inherently self-preserving but the term must be accurate if used), or 'dermatologist-tested' without documented clinical evidence.", evidenceNote: "Label and marketing material review." },
    { ref: "C.1", section: "C", order: 1, text: "Heavy metal panel (Pb, Cd, Hg, As, Zn by ICP-MS or AAS) conducted on the cocoa pod ash ingredient at minimum every 6 months, or with each new harvest season / new supplier source. This is non-negotiable — heavy metal content varies by farm location and cannot be assumed to be consistent.", evidenceNote: "Ash heavy metal COA — lot-specific, current within 6 months, from accredited lab." },
    { ref: "C.2", section: "C", order: 2, text: "Finished product heavy metal panel conducted at minimum annually and with each new ash source. EU Cosmetics Regulation limits for heavy metals in rinse-off cosmetics: Pb ≤ 10 mg/kg, Cd ≤ 5 mg/kg, Hg ≤ 1 mg/kg, As ≤ 5 mg/kg. NAFDAC mirrors EU limits for export-oriented products.", evidenceNote: "Finished product heavy metal COA — current within 12 months." },
    { ref: "C.3", section: "C", order: 3, text: "Cocoa pod farm location assessed for soil contamination risk: avoidance of cocoa sourced from regions adjacent to mining operations, smelting facilities, or heavily industrialised agriculture where cadmium, lead, and arsenic soil contamination is documented.", evidenceNote: "Farm location documentation; any available soil analysis; certification body audit report." },
    { ref: "C.4", section: "C", order: 4, text: "Ash burn process controlled: pods are fully dried before burning; burning temperature is not excessively high (above 700°C, heavy metals become more volatile and soluble in the resulting ash). Burn temperature target documented in production SOP.", evidenceNote: "Production SOP; burn temperature records where thermometer is used." },
    { ref: "C.5", section: "C", order: 5, text: "Ash sieving and lye filtration documented: visible ash particles are removed before lye solution enters the saponification vessel. This reduces, but does not eliminate, heavy metal carry-through — hence the need for finished product testing.", evidenceNote: "Lye filtration SOP; batch production records." },
    { ref: "D.1", section: "D", order: 1, text: "Oil weight (or volume with density correction) is measured for every batch. Ad-hoc or 'by eye' oil dosing without measurement is a Major finding — it makes consistent saponification impossible and free alkali control unreliable.", evidenceNote: "Batch production records — oil weight/volume per batch." },
    { ref: "D.2", section: "D", order: 2, text: "Lye strength is assessed before each batch. At minimum: a physical float test (potato or egg) with documented pass/fail; ideally: hydrometer reading (Baumé or Brix) or titration with a target range defined in the SOP.", evidenceNote: "Lye strength testing method documented in SOP; batch records showing lye check result." },
    { ref: "D.3", section: "D", order: 3, text: "Cook time and stirring frequency are consistent across batches and documented. The production SOP defines minimum cook time, target temperature range, and saponification endpoint assessment method.", evidenceNote: "Production SOP; batch production records." },
    { ref: "D.4", section: "D", order: 4, text: "Saponification endpoint confirmed before moulding: visual trace assessment, spoon trace, blender trace, or zap test (with safety precautions documented). No product moulded from a batch that has not reached trace.", evidenceNote: "SOP for trace assessment; batch records." },
    { ref: "D.5", section: "D", order: 5, text: "Curing time is documented and enforced: minimum 4 weeks before release; 6–8 weeks for export. pH is tested at end of cure period — bars not released if pH > 10.5. Evidence that rejected batches are held and re-tested, not sold.", evidenceNote: "Batch curing records; pH test log at cure completion." },
    { ref: "D.6", section: "D", order: 6, text: "Saponification vessels are stainless steel, food-grade aluminium-free polymer, or enamel — never bare aluminium. Alkali attacks aluminium, introducing aluminium contamination into the product.", evidenceNote: "Visual inspection of production vessels; vessel material documented in GMP records." },
    { ref: "E.1", section: "E", order: 1, text: "pH of finished, cured bar tested per batch using calibrated pH meter (dissolved in distilled water at 1% concentration per ISO 4316:1977). Target: pH 8.5–10.5. Bars with pH > 10.5 are placed on hold and re-tested after additional curing. pH > 11.0 on a cured bar is a Critical finding.", evidenceNote: "pH test log — per batch; pH meter calibration record." },
    { ref: "E.2", section: "E", order: 2, text: "Free alkali (free caustic) tested per batch by phenolphthalein titration method (AOCS Tf 1a-64 or equivalent). Free alkali expressed as % KOH; target: ≤ 0.10% KOH for a safe finished bar. Any batch exceeding 0.10% is quarantined pending further curing and re-testing.", evidenceNote: "Free alkali titration records; batch quarantine log where applicable." },
    { ref: "E.3", section: "E", order: 3, text: "Total fatty matter (TFM) tested at minimum quarterly to confirm saponification efficiency and detect under-processed batches. Target TFM ≥ 60% for a standard African black soap bar (IS 7769 / BIS standard used as reference).", evidenceNote: "TFM test report — quarterly minimum; accredited lab preferred." },
    { ref: "E.4", section: "E", order: 4, text: "Moisture content of finished bar tested: target ≤ 15% moisture for shelf-stable product. High moisture indicates under-curing and accelerates microbial risk and rancidity of retained oils.", evidenceNote: "Moisture content records; drying oven or moisture analyser used." },
    { ref: "E.5", section: "E", order: 5, text: "Lather quality assessment: representative bars from each batch evaluated for lather volume and creaminess. Batches with significantly reduced lather vs. specification are flagged for investigation (may indicate saponification failure or oil rancidity).", evidenceNote: "Organoleptic evaluation records per batch." },
    { ref: "E.6", section: "E", order: 6, text: "Colour, texture, and scent evaluated per batch against an approved reference standard bar: acceptable natural variation documented; off-colours (bright orange, bleached white) or foreign odours (musty, rancid) trigger quarantine.", evidenceNote: "Sensory evaluation records; approved reference standard." },
    { ref: "F.1", section: "F", order: 1, text: "Total aerobic microbial count (TAMC) tested on finished product: target ≤ 100 CFU/g for rinse-off products (EU Cosmetics Regulation 1223/2009 Annex I; ISO 21148:2017 method). Well-cured, dry black soap typically achieves < 10 CFU/g.", evidenceNote: "Microbial COA — TAMC; accredited external lab." },
    { ref: "F.2", section: "F", order: 2, text: "Staphylococcus aureus: absent in 1g (EU requirement for rinse-off cosmetics). A skin-contact product contaminated with S. aureus poses infection risk — particularly for consumers with compromised skin barrier.", evidenceNote: "Microbial COA — S. aureus; ISO 22718:2015 method." },
    { ref: "F.3", section: "F", order: 3, text: "Pseudomonas aeruginosa: absent in 1g (EU requirement). P. aeruginosa can colonise moist cosmetic production environments and is a particular risk in water-intensive processes. Confirm environmental swab programme covers mixing vessels and water handling equipment.", evidenceNote: "Microbial COA — Pseudomonas; ISO 22717:2015 method; environmental swab records." },
    { ref: "F.4", section: "F", order: 4, text: "Yeast and mould count: ≤ 100 CFU/g (TYMC) for rinse-off cosmetics. Elevated mould counts in a soap bar typically indicate excessive moisture or contaminated botanical additives.", evidenceNote: "Microbial COA — yeast and mould count." },
    { ref: "F.5", section: "F", order: 5, text: "If optional botanicals (herbs, clays, dried petals) are incorporated, a separate microbial check on the botanical ingredient is conducted before inclusion — botanical additives are the leading source of microbial contamination in natural soap products.", evidenceNote: "Botanical ingredient microbial test report." },
    { ref: "G.1", section: "G", order: 1, text: "Palm kernel oil: Certificate of Analysis per lot confirming free fatty acid ≤ 3%, peroxide value ≤ 10 meq O₂/kg, moisture ≤ 0.15%, and no rancid odour. Oil beyond these parameters has begun to oxidise — it will produce a rancid-smelling soap and may cause skin irritation.", evidenceNote: "Palm kernel oil COA — lot-specific; sensory check at intake." },
    { ref: "G.2", section: "G", order: 2, text: "Shea butter: COA per lot confirming free fatty acid ≤ 5%, peroxide value ≤ 5 meq O₂/kg. Unrefined shea should retain its characteristic off-white colour and nutty scent. Bleached, deodorised, or hydrogenated shea is not appropriate for an organic-claimed product.", evidenceNote: "Shea butter COA; INCI confirmation (unrefined = BUTYROSPERMUM PARKII BUTTER not PARKII KERNEL OIL)." },
    { ref: "G.3", section: "G", order: 3, text: "Coconut oil (where used): COA confirming free fatty acid ≤ 0.5%, peroxide value ≤ 10 meq O₂/kg, moisture ≤ 0.1%. Virgin coconut oil preferred for organic-claimed product; RBD coconut oil is acceptable for conventional or semi-artisanal product if disclosed.", evidenceNote: "Coconut oil COA; origin and processing method documented." },
    { ref: "G.4", section: "G", order: 4, text: "All oils stored in sealed containers, protected from light and heat (target: storage temperature ≤ 25°C for palm kernel; ≤ 28°C for coconut oil in solid form). Oil storage temperature log maintained, or temperature-controlled storage demonstrated.", evidenceNote: "Oil storage temperature records; visual inspection of storage area." },
    { ref: "G.5", section: "G", order: 5, text: "Oil intake inspection conducted on every delivery: sensory check (colour, odour, viscosity) and peroxide value rapid test or supplier COA reviewed before acceptance. Rancid oil intake rejected — supplier incident logged.", evidenceNote: "Oil intake inspection log; rejection records." },
    { ref: "H.1", section: "H", order: 1, text: "Master cleaning and sanitation schedule documented and implemented for all production equipment. All vessels, moulds, cutting tools, and surfaces cleaned and sanitised after each production run. Stainless steel or food-grade polymer surfaces preferred — no porous wooden surfaces in direct product contact.", evidenceNote: "Cleaning schedule; sanitation records; equipment inspection." },
    { ref: "H.2", section: "H", order: 2, text: "Sanitisers used are food-safe (no chlorinated compounds that could react with organic oils to form harmful by-products; no rinse-incompatible agents). Concentration and dwell time documented.", evidenceNote: "Sanitiser MSDS; cleaning log with concentration records." },
    { ref: "H.3", section: "H", order: 3, text: "All production staff wear appropriate PPE during saponification: chemical-resistant gloves, eye protection (goggles), and protective apron when handling lye solution. Lye splash is a chemical burn hazard. PPE use confirmed during walkthrough.", evidenceNote: "Visual inspection; PPE policy; staff training records." },
    { ref: "H.4", section: "H", order: 4, text: "Staff trained in GMP, personal hygiene, and lye safety. Training records include: date, content covered, trainer name, and sign-off by each trained individual. Refresher training conducted at minimum annually.", evidenceNote: "Training matrix; training attendance records." },
    { ref: "H.5", section: "H", order: 5, text: "Health screening policy: staff with open wounds, skin infections, or gastroenteric illness excluded from production. Medical fitness declarations on file.", evidenceNote: "Health declaration policy; staff health screening records." },
    { ref: "H.6", section: "H", order: 6, text: "Pest control programme: active, contracted service with monthly visits; bait station map maintained; activity log current. Special attention to stored-product insects in oil and botanical storage areas.", evidenceNote: "Pest control contract; bait station map; activity log." },
    { ref: "I.1", section: "I", order: 1, text: "INCI ingredient list present on label, listed in descending order of weight at time of manufacture, using correct INCI nomenclature (e.g., THEOBROMA CACAO POD ASH, not 'cocoa ash' or 'black soap ash'). This is a mandatory requirement under both NAFDAC 2023 Regulations and EU Reg. 1223/2009 Art. 19.", evidenceNote: "Label artwork; INCI list verification against formula." },
    { ref: "I.2", section: "I", order: 2, text: "NAFDAC registration number prominently displayed on primary packaging in the format prescribed by NAFDAC Labelling Regulations 2023.", evidenceNote: "Label artwork; NAFDAC certificate number cross-check." },
    { ref: "I.3", section: "I", order: 3, text: "Net weight declared accurately in grams. Verify against weight check records — at least 5 bars per batch weighed; average weight meets declared weight; no bar below the tolerated negative error.", evidenceNote: "Label weight declaration; weight check records." },
    { ref: "I.4", section: "I", order: 4, text: "Batch code and best-before date legibly printed or stamped. Batch code traceable to the full batch production record held by the supplier.", evidenceNote: "Label inspection; batch production record traceability exercise." },
    { ref: "I.5", section: "I", order: 5, text: "Organic claim on label substantiated — supported by documentation (see Section 3). If ISO 16128-2 organic percentage is stated, it is accurate. No claim suggesting the product is medicinal, pharmaceutical, or a skin treatment beyond normal cosmetic claims (i.e., no disease claims).", evidenceNote: "Label claim vs. certification documentation; ISO 16128-2 calculation." },
    { ref: "I.6", section: "I", order: 6, text: "Shelf-life claim (best-before date) supported by stability testing. Minimum acceptable: a 6-month accelerated stability study at 40°C/75% RH (ICH Q1B or equivalent cosmetics stability protocol) demonstrating no significant change in pH, colour, odour, or microbial quality.", evidenceNote: "Stability test report; best-before date vs. stability data." },
    { ref: "I.7", section: "I", order: 7, text: "If product is exported to the EU: Product Information File (PIF) is prepared and maintained at the EU Responsible Person address, as required by EU Regulation 1223/2009 Art. 11. CPNP (Cosmetic Products Notification Portal) notification is on file.", evidenceNote: "PIF contents checklist; CPNP notification confirmation." },
    { ref: "J.1", section: "J", order: 1, text: "Written product recall and withdrawal SOP in place, tested via a documented mock recall exercise within the past 12 months. For a bar soap, the minimum requirement is: identify the affected batch number, locate all units distributed, and initiate contact with distributors/retailers within 24 hours.", evidenceNote: "Recall SOP; mock recall drill record; distribution records." },
    { ref: "J.2", section: "J", order: 2, text: "Batch traceability system in place: select any finished batch → trace to specific oil lot numbers, ash burn batch, production date, and cure date. One-step-back (to raw material supplier) and one-step-forward (to customer) must be demonstrable.", evidenceNote: "Batch traceability records; demonstrated traceability exercise." },
    { ref: "J.3", section: "J", order: 3, text: "Complaint management system in place with written log, root cause analysis for any quality or safety complaint, and documented corrective action. Any complaint involving skin irritation, rash, or chemical burn treated as a potential safety incident and escalated to the Manager of SQA within 24 hours.", evidenceNote: "Complaint log; RCA records; escalation procedure." },
    { ref: "J.4", section: "J", order: 4, text: "AfCFTA Certificate of Origin in place for cross-border shipments within Africa. Destination-market compliance verified for specific requirements (e.g., EU CPNP notification, UK SCPN, USA FDA voluntary registration).", evidenceNote: "Certificate of Origin; export registration documents." },
  ],
};

